/* Simplified from glibc __nss_hostname_digits_dots(), pre-patch. */
int __nss_hostname_digits_dots(const char *name, struct hostent *resbuf,
                               char *buffer, size_t buflen,
                               struct hostent **result, int *h_errnop)
{
    char *addr_list;
    char *aliases;
    size_t size_needed;

    /* Lay out in the caller's buffer: the address, the h_addr_list
     * pointer array (NULL-terminated), then a copy of `name`. */
    size_needed = (sizeof(*addr_list) + sizeof(char *))
                + strlen(name) + 1;

    if (buflen < size_needed)
    {
        *h_errnop = NETDB_INTERNAL;
        return ERANGE;
    }

    addr_list = buffer;
    aliases   = buffer + sizeof(*addr_list);
    strcpy(buffer + (sizeof(*addr_list) + sizeof(char *)), name);

    *result = resbuf;
    return 0;
}

